/**
 * Keeps generated output branded as AI Job Copilot.
 *
 * Models occasionally add self-attribution ("Generated by ChatGPT", "As an AI language model, ...").
 * Those phrases are removed from generated text ONLY when they do not appear in the source prompt,
 * so legitimate user content (e.g. a project "powered by OpenAI", an employer named Anthropic,
 * or a "Gemini API" skill) is never altered.
 */

export const PRODUCT_NAME = "AI Job Copilot";

export const BRANDING_RULE =
  `You are part of ${PRODUCT_NAME}. Never name or refer to the underlying AI model, vendor or provider, and never add "generated by" or similar attributions. ` +
  "Keep tool, company and skill names exactly as they appear in the user's own data.";

const PROVIDER = String.raw`(?:chat\s?gpt|openai|gpt-?\d[\w.-]*|google\s+gemini|gemini(?:\s+(?:pro|flash|ultra))?|groq|llama[\w.-]*|meta\s+llama|claude|anthropic|mistral|bard)`;

const PATTERNS: RegExp[] = [
  // "(Generated by ChatGPT)", "Written with OpenAI GPT-4o." etc.
  new RegExp(String.raw`\s*\(?\s*\b(?:generated|written|created|produced|drafted|composed)\s+(?:by|with|using|via)\s+(?:the\s+)?${PROVIDER}(?:\s+${PROVIDER})*(?:\s+(?:ai|model|assistant))?\s*\)?\.?`, "gi"),
  // "As an AI language model, ..." / "As a large language model trained by OpenAI, ..."
  /\bas an? (?:ai|artificial intelligence|large) (?:language )?model(?:\s+(?:trained|developed|created) by [\w\s.-]+?)?\s*,\s*/gi,
  // "I'm ChatGPT, ..." / "I am Gemini." (whole self-identification sentence)
  new RegExp(String.raw`\bI(?:'m| am)\s+${PROVIDER}\b[^.!?\n]*[.!?]?\s*`, "gi")
];

function scrubString(text: string, source: string): string {
  let output = text;
  let removedLeading = false;
  for (const pattern of PATTERNS) {
    output = output.replace(pattern, (match: string, ...args: unknown[]) => {
      if (source.includes(match.trim().toLowerCase())) return match;
      const offset = args[args.length - 2];
      if (offset === 0 || output.slice(0, Number(offset)).trim() === "") removedLeading = true;
      return "";
    });
  }
  if (output === text) return text;
  output = output.replace(/[ \t]{2,}/g, " ").replace(/[ \t]+([.,;:!?])/g, "$1").trim();
  return removedLeading && output ? output.charAt(0).toUpperCase() + output.slice(1) : output;
}

/** Deep-scrubs provider self-attribution from generated data. Non-string values are returned unchanged. */
export function scrubProviderAttribution<T>(value: T, sourceText = ""): T {
  const source = sourceText.toLowerCase();
  const walk = (input: unknown, depth: number): unknown => {
    if (depth > 12) return input;
    if (typeof input === "string") return scrubString(input, source);
    if (Array.isArray(input)) return input.map((item) => walk(item, depth + 1));
    if (input && typeof input === "object" && Object.getPrototypeOf(input) === Object.prototype) {
      return Object.fromEntries(Object.entries(input as Record<string, unknown>).map(([key, item]) => [key, walk(item, depth + 1)]));
    }
    return input;
  };
  return walk(value, 0) as T;
}
